  void attachMainPlayer(){if(playerView==null){playerView=new PlayerView(this);playerView.setUseController(true);playerView.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);playerView.setFocusable(true);}applyResizeMode(playerView);ViewParent p=playerView.getParent();if(p instanceof ViewGroup)((ViewGroup)p).removeView(playerView);if(homePlayerHolder!=null){homePlayerHolder.addView(playerView,0,new FrameLayout.LayoutParams(-1,-1));if(player!=null)playerView.setPlayer(player);ensureSubtitleLayer();}}

  void initPlayer(){player=new ExoPlayer.Builder(this).build();applyLanguagePrefs();player.addListener(new Player.Listener(){
    @Override public void onPlaybackStateChanged(int s){
      if(s==Player.STATE_READY){cancelStartupWatchdog();retries=0;long ms=connectStartedAt>0?SystemClock.elapsedRealtime()-connectStartedAt:0;setHealth(current,ms>2500?HEALTH_WARN:HEALTH_OK,ms>2500?"Lento":"Disponible",ms);setLiveStatus("En vivo"+channelPositionText(),CYAN);}
      else if(s==Player.STATE_BUFFERING)setLiveStatus(retries>0?"Reconectando "+retries+"/3…":"Cargando señal…",CYAN);
      else if(s==Player.STATE_ENDED)setLiveStatus("Transmisión finalizada",ORANGE);
    }
    @Override public void onIsPlayingChanged(boolean playing){if(playing&&player.getPlaybackState()==Player.STATE_READY)setLiveStatus("En vivo"+channelPositionText(),CYAN);}
    @Override public void onPlayerError(PlaybackException e){cancelStartupWatchdog();setHealth(current,HEALTH_BAD,"Problema",0);setLiveStatus(errorLabel(e),ORANGE);if(autoRetryEnabled)autoRetry();}
  });attachMainPlayer();ensureSubtitleLayer();}

  void ensureSubtitleLayer(){try{if(playerView!=null&&playerView.getSubtitleView()!=null){playerView.getSubtitleView().setVisibility(View.VISIBLE);playerView.getSubtitleView().setApplyEmbeddedStyles(true);playerView.getSubtitleView().setApplyEmbeddedFontSizes(true);}}catch(Exception ignored){}}
  String langLabel(String code){if(code==null||"auto".equals(code))return "Automático";if("off".equals(code))return "Desactivados";if("es".equals(code))return "Español";if("en".equals(code))return "Inglés";if("pt".equals(code))return "Portugués";if("fr".equals(code))return "Francés";if("de".equals(code))return "Alemán";if("it".equals(code))return "Italiano";return code;}
  void applyLanguagePrefs(){if(player==null)return;TrackSelectionParameters.Builder b=player.getTrackSelectionParameters().buildUpon();b.setPreferredAudioLanguage("auto".equals(preferredAudioLang)?null:preferredAudioLang);if("off".equals(preferredSubtitleLang)){b.setTrackTypeDisabled(C.TRACK_TYPE_TEXT,true);b.setPreferredTextLanguage(null);}else{b.setTrackTypeDisabled(C.TRACK_TYPE_TEXT,false);b.setPreferredTextLanguage("auto".equals(preferredSubtitleLang)?null:preferredSubtitleLang);b.setSelectUndeterminedTextLanguage(true);}player.setTrackSelectionParameters(b.build());ensureSubtitleLayer();}
  void chooseLanguage(boolean audio){String[] labels=audio?new String[]{"Automático","Español","Inglés","Portugués","Francés","Alemán","Italiano"}:new String[]{"Automático","Desactivados","Español","Inglés","Portugués","Francés","Alemán","Italiano"};String[] codes=audio?new String[]{"auto","es","en","pt","fr","de","it"}:new String[]{"auto","off","es","en","pt","fr","de","it"};AlertDialog d=new AlertDialog.Builder(this).setTitle(audio?"Idioma de audio":"Idioma de subtítulos").setItems(labels,(x,w)->{if(audio)preferredAudioLang=codes[w];else preferredSubtitleLang=codes[w];savePrefs();applyLanguagePrefs();showLanguageSettings();}).setNegativeButton("Cancelar",null).create();styleDialog(d);}
  void showLanguageSettings(){LinearLayout p=pageBase("Idioma","Preferencias de reproducción");Button audio=menuCard("Audio · "+langLabel(preferredAudioLang),"Se aplica cuando el canal ofrece ese idioma",R.drawable.pv_ic_audio),subs=menuCard("Subtítulos · "+langLabel(preferredSubtitleLang),"Se aplica cuando el canal ofrece esa pista",R.drawable.pv_ic_subtitles);for(Button b:new Button[]{audio,subs}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(68));lp.setMargins(0,dp(7),0,dp(7));p.addView(b,lp);}audio.setOnClickListener(v->chooseLanguage(true));subs.setOnClickListener(v->chooseLanguage(false));}  void showMediaLanguageMenu(){String[] opts={"Audio / idioma","Subtítulos / idioma","Preferencias globales"};AlertDialog d=new AlertDialog.Builder(this).setTitle("Idioma").setItems(opts,(x,w)->{if(w==0)showTracks(C.TRACK_TYPE_AUDIO);else if(w==1)showTracks(C.TRACK_TYPE_TEXT);else showLanguageSettings();}).setNegativeButton("Cerrar",null).create();styleDialog(d);}

  String programText(Channel ch){Program p=currentPrograms.get(ch.id);if(p==null)return "Programa · guía no disponible";return p.title+"  ·  "+hhmm(p.start)+"–"+hhmm(p.stop);}
  String hhmm(long ms){return new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(ms));}
  void bindLogo(ImageView iv,Channel ch){iv.setTag(ch.id);Bitmap b=ch.logo.isEmpty()?null:logoCache.get(ch.logo);if(b!=null){iv.setAlpha(1f);iv.setImageBitmap(b);return;}iv.setAlpha(.38f);iv.setImageResource(R.drawable.pv_logo);if(ch.logo.isEmpty()||!logoLoading.add(ch.logo))return;final String url=ch.logo,id=ch.id;imageIo.submit(()->{Bitmap bmp=null;InputStream in=null;try{URLConnection cn=new URL(url).openConnection();cn.setConnectTimeout(3500);cn.setReadTimeout(4500);cn.setRequestProperty("User-Agent","PalmaVision/2.2.2");in=cn.getInputStream();bmp=BitmapFactory.decodeStream(in);}catch(Exception ignored){}finally{try{if(in!=null)in.close();}catch(Exception ignored){}logoLoading.remove(url);}if(bmp!=null){logoCache.put(url,bmp);final Bitmap ready=bmp;mainHandler.post(()->{if(id.equals(iv.getTag())){iv.setAlpha(1f);iv.setImageBitmap(ready);}});}});}
  void setHealth(Channel ch,int state,String text,long latency){if(ch==null)return;channelHealth.put(ch.id,new Health(state,text,latency,System.currentTimeMillis()));if(adapter!=null)adapter.notifyDataSetChanged();}
  int healthColor(Channel ch){Health h=channelHealth.get(ch.id);if(h==null)return MUTED;if(h.state==HEALTH_OK)return GREEN;if(h.state==HEALTH_WARN)return ORANGE;if(h.state==HEALTH_BAD)return PV_ERROR;if(h.state==HEALTH_VERIFIED)return CYAN;return MUTED;}
  String healthText(Channel ch){Health h=channelHealth.get(ch.id);return h==null?"Sin verificar":h.text;}

