  void createParentalPin(Runnable ok){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(8),dp(16),0);EditText a=pinField("PIN de 4 dígitos"),b=pinField("Confirmar PIN");for(EditText e:new EditText[]{a,b}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(50));p.setMargins(0,dp(5),0,dp(5));box.addView(e,p);}AlertDialog d=new AlertDialog.Builder(this).setTitle("Crear PIN parental").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(x,w)->{String p1=a.getText().toString(),p2=b.getText().toString();if(p1.length()!=4||!p1.equals(p2)){toast("El PIN debe tener 4 dígitos y coincidir");return;}parentalPinHash=sha1(p1);parentalEnabled=true;savePrefs();toast("Control parental activado");if(ok!=null)ok.run();}).create();styleDialog(d);}
