  void showLists(){clearContent();LinearLayout page=pageBase("Fuentes de TV","Elige cómo cargar tus canales");TextView current=tv("Fuente actual  ·  "+activeSourceLabel+"\nGuía  ·  "+activeEpgLabel,12,CYAN);current.setPadding(dp(12),dp(8),dp(12),dp(8));current.setBackground(rounded(PV_SURFACE_2,12));page.addView(current,new LinearLayout.LayoutParams(-1,dp(58)));Button principal=menuCard("Lista PalmaVision","Lista principal incluida · 1,733 canales",R.drawable.pv_ic_list),local=menuCard("Archivo M3U local","Selecciona un archivo desde el teléfono",R.drawable.pv_ic_list),url=menuCard("URL M3U","Enlace directo + EPG XMLTV opcional",R.drawable.pv_ic_globe),xtream=menuCard("Servidor IPTV / Xtream","URL + usuario + contraseña · EPG automático",R.drawable.pv_ic_settings),epg=menuCard("Guía EPG / XMLTV","Conecta o cambia la programación",R.drawable.pv_ic_news);for(Button b:new Button[]{principal,local,url,xtream,epg}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(68));p.setMargins(0,dp(7),0,0);page.addView(b,p);}principal.setOnClickListener(v->{SharedPreferences.Editor e=getSharedPreferences("tvplus",MODE_PRIVATE).edit();clearSourceKeys(e).putString("source_type","default").apply();clearEpg();loadDefault();showLiveCategories();});local.setOnClickListener(v->pickM3u());url.setOnClickListener(v->askUrl());xtream.setOnClickListener(v->askXtream());epg.setOnClickListener(v->askEpg());}
  void pickM3u(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,OPEN_M3U);}
  @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==OPEN_M3U&&res==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}SharedPreferences.Editor e=getSharedPreferences("tvplus",MODE_PRIVATE).edit();clearSourceKeys(e).putString("source_type","local").putString("m3u_uri",u.toString()).apply();clearEpg();loadFromUri(u,"Archivo M3U local");showLiveCategories();}}
  void askUrl(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(16),dp(8),dp(16),0);EditText m3u=sourceField("URL M3U · https://servidor/lista.m3u",false),epg=sourceField("EPG XMLTV opcional · https://servidor/epg.xml",false);m3u.setText(p.getString("m3u_url",""));epg.setText(p.getString("epg_url",""));for(EditText f:new EditText[]{m3u,epg}){LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(50));fp.setMargins(0,dp(6),0,0);form.addView(f,fp);}AlertDialog d=new AlertDialog.Builder(this).setTitle("URL M3U").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Cargar",(x,w)->{String u=m3u.getText().toString().trim(),eurl=epg.getText().toString().trim();if(u.startsWith("http://")||u.startsWith("https://")){SharedPreferences.Editor ed=getSharedPreferences("tvplus",MODE_PRIVATE).edit();clearSourceKeys(ed).putString("source_type","url").putString("m3u_url",u).putString("epg_url",eurl).apply();clearEpg();if(!eurl.isEmpty())queueEpg(eurl,"XMLTV");loadFromUrl(u,"URL M3U");showLiveCategories();}else toast("Ingrese una URL válida");}).create();styleDialog(d);}
  void askXtream(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(16),dp(8),dp(16),0);EditText name=sourceField("Nombre de la lista · Casa, IPTV, Proveedor…",false),server=sourceField("URL del servidor · http(s)://host:puerto",false),user=sourceField("Usuario",false),pass=sourceField("Contraseña",true);name.setText(p.getString("xtream_name",""));server.setText(p.getString("xtream_server",""));user.setText(p.getString("xtream_user",""));pass.setText(p.getString("xtream_pass",""));for(EditText f:new EditText[]{name,server,user,pass}){LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(50));fp.setMargins(0,dp(6),0,dp(4));form.addView(f,fp);}AlertDialog d=new AlertDialog.Builder(this).setTitle("Servidor IPTV / Xtream").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Conectar",(x,w)->{String n=name.getText().toString().trim(),s=server.getText().toString().trim(),u=user.getText().toString().trim(),pw=pass.getText().toString();if(n.isEmpty())n="Mi IPTV";if(!(s.startsWith("http://")||s.startsWith("https://"))||u.isEmpty()||pw.isEmpty()){toast("Completa URL, usuario y contraseña");return;}SharedPreferences.Editor ed=getSharedPreferences("tvplus",MODE_PRIVATE).edit();clearSourceKeys(ed).putString("source_type","xtream").putString("xtream_name",n).putString("xtream_server",s).putString("xtream_user",u).putString("xtream_pass",pw).apply();clearEpg();loadXtream(s,u,pw,n);showLiveCategories();}).create();styleDialog(d);}
  String xtreamM3uUrl(String server,String user,String pass){try{String s=server.endsWith("/")?server.substring(0,server.length()-1):server;return s+"/get.php?username="+URLEncoder.encode(user,"UTF-8")+"&password="+URLEncoder.encode(pass,"UTF-8")+"&type=m3u_plus&output=ts";}catch(Exception e){return "";}}
  String xtreamEpgUrl(String server,String user,String pass){try{String s=server.endsWith("/")?server.substring(0,server.length()-1):server;return s+"/xmltv.php?username="+URLEncoder.encode(user,"UTF-8")+"&password="+URLEncoder.encode(pass,"UTF-8");}catch(Exception e){return "";}}
  void loadXtream(String server,String user,String pass,String name){String u=xtreamM3uUrl(server,user,pass),e=xtreamEpgUrl(server,user,pass);if(u.isEmpty()){toast("No se pudo construir la URL del servidor");return;}clearEpg();if(!e.isEmpty())queueEpg(e,"EPG Xtream");loadFromUrl(u,name==null||name.trim().isEmpty()?"Mi IPTV":name.trim());}
  void queueEpg(String url,String label){pendingEpgUrl=url==null?"":url.trim();pendingEpgLabel=label==null?"EPG":label;if(!pendingEpgUrl.isEmpty()&&!all.isEmpty()){String u=pendingEpgUrl,l=pendingEpgLabel;pendingEpgUrl="";pendingEpgLabel="";loadXmltv(u,l);}}
  void askEpg(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);final EditText e=sourceField("https://servidor/epg.xml",false);e.setText(p.getString("epg_url",""));AlertDialog d=new AlertDialog.Builder(this).setTitle("Guía EPG / XMLTV").setView(e).setNegativeButton("Cancelar",null).setNeutralButton("Quitar guía",(x,w)->{getSharedPreferences("tvplus",MODE_PRIVATE).edit().remove("epg_url").apply();clearEpg();}).setPositiveButton("Cargar",(x,w)->{String u=e.getText().toString().trim();if(u.startsWith("http://")||u.startsWith("https://")){getSharedPreferences("tvplus",MODE_PRIVATE).edit().putString("epg_url",u).apply();queueEpg(u,"XMLTV");}else toast("Ingrese una URL XMLTV válida");}).create();styleDialog(d);}
  void clearEpg(){currentPrograms.clear();programGuide.clear();lastEpgUrl="";activeEpgLabel="Sin EPG";epgLastError="";epgLoading=false;if(adapter!=null)adapter.notifyDataSetChanged();}
  long parseXmltvTime(String raw){try{Matcher m=Pattern.compile("^(\\d{14})(?:\\s*([+-]\\d{4}))?").matcher(raw==null?"":raw.trim());if(!m.find())return 0L;String zone=m.group(2);SimpleDateFormat f=new SimpleDateFormat(zone==null?"yyyyMMddHHmmss":"yyyyMMddHHmmss Z",Locale.US);f.setLenient(false);return f.parse(m.group(1)+(zone==null?"":" "+zone)).getTime();}catch(Exception e){return 0L;}}
  InputStream xmltvStream(URLConnection cn,String url)throws IOException{InputStream in=cn.getInputStream();String enc=cn.getContentEncoding();if((enc!=null&&enc.toLowerCase(Locale.ROOT).contains("gzip"))||url.toLowerCase(Locale.ROOT).endsWith(".gz"))return new GZIPInputStream(in);return in;}
  List<String> epgCandidates(String raw){LinkedHashSet<String> out=new LinkedHashSet<>();if(raw!=null)for(String part:raw.split(",")){String u=part.trim();if(u.isEmpty())continue;out.add(u);if(u.toLowerCase(Locale.ROOT).endsWith(".xml.gz"))out.add(u.substring(0,u.length()-3));else if(u.toLowerCase(Locale.ROOT).endsWith(".xml"))out.add(u+".gz");}return new ArrayList<>(out);}
  void loadXmltv(String url,String label){lastEpgUrl=url;activeEpgLabel="Cargando EPG…";epgLastError="";epgLoading=true;epgIo.submit(()->{ConcurrentHashMap<String,Program> fresh=new ConcurrentHashMap<>();ConcurrentHashMap<String,List<Program>> schedules=new ConcurrentHashMap<>();InputStream in=null;String used="";Exception last=null;try{HashSet<String> wanted=new HashSet<>();for(Channel ch:all)wanted.add(ch.id);for(String candidate:epgCandidates(url)){try{URLConnection cn=new URL(candidate).openConnection();cn.setConnectTimeout(10000);cn.setReadTimeout(45000);cn.setRequestProperty("User-Agent","PalmaVision/2.2.2");cn.setRequestProperty("Accept","application/xml,text/xml,application/gzip,*/*");if(cn instanceof HttpURLConnection){HttpURLConnection h=(HttpURLConnection)cn;h.setInstanceFollowRedirects(true);int code=h.getResponseCode();if(code<200||code>=400)throw new FileNotFoundException("HTTP "+code+" · "+candidate);}in=xmltvStream(cn,candidate);XmlPullParser x=Xml.newPullParser();x.setInput(in,"UTF-8");long now=System.currentTimeMillis(),limit=now+24L*60L*60L*1000L;String ch=null,start=null,stop=null,ptitle="";boolean wantedChannel=false;for(int ev=x.getEventType();ev!=XmlPullParser.END_DOCUMENT;ev=x.next()){if(ev==XmlPullParser.START_TAG&&"programme".equals(x.getName())){ch=x.getAttributeValue(null,"channel");wantedChannel=ch!=null&&wanted.contains(ch);start=x.getAttributeValue(null,"start");stop=x.getAttributeValue(null,"stop");ptitle="";}else if(ev==XmlPullParser.START_TAG&&"title".equals(x.getName())&&ch!=null){String tx=x.nextText();if(wantedChannel)ptitle=tx;}else if(ev==XmlPullParser.END_TAG&&"programme".equals(x.getName())&&ch!=null){if(wantedChannel){long s=parseXmltvTime(start),e=parseXmltvTime(stop);if(s>0&&e>0){Program pr=new Program(ptitle.isEmpty()?"Programa":ptitle,s,e);if(now>=s&&now<e)fresh.put(ch,pr);if(e>=now-30L*60L*1000L&&s<=limit){List<Program> list=schedules.get(ch);if(list==null){list=new ArrayList<>();schedules.put(ch,list);}if(list.size()<32)list.add(pr);}}}ch=null;wantedChannel=false;}}used=candidate;last=null;break;}catch(Exception ex){last=ex;fresh.clear();schedules.clear();try{if(in!=null)in.close();}catch(Exception ignored){}in=null;}}if(used.isEmpty()){if(last!=null)throw last;throw new FileNotFoundException("No se encontró una URL EPG disponible");}for(List<Program> list:schedules.values())Collections.sort(list,(a,b)->Long.compare(a.start,b.start));currentPrograms.clear();currentPrograms.putAll(fresh);programGuide.clear();programGuide.putAll(schedules);final String okUrl=used;mainHandler.post(()->{epgLoading=false;epgLastError="";lastEpgUrl=okUrl;activeEpgLabel=label+" · "+fresh.size()+" ahora · "+schedules.size()+" canales";if(adapter!=null)adapter.notifyDataSetChanged();});}catch(Exception ex){final String err=ex.getClass().getSimpleName()+(ex.getMessage()==null?"":" · "+ex.getMessage());mainHandler.post(()->{epgLoading=false;epgLastError=err;activeEpgLabel="EPG con error";if(adapter!=null)adapter.notifyDataSetChanged();});}finally{try{if(in!=null)in.close();}catch(Exception ignored){}}});}

  String nowNextText(Channel ch){List<Program> list=programGuide.get(ch.id);if(list==null||list.isEmpty())return "Sin programación disponible";long now=System.currentTimeMillis();Program nowP=null,next=null;for(Program p:list){if(now>=p.start&&now<p.stop)nowP=p;else if(p.start>now){next=p;break;}}String s=nowP==null?"Ahora · sin datos":"Ahora · "+nowP.title+" · "+hhmm(nowP.start)+"–"+hhmm(nowP.stop);if(next!=null)s+="\nDespués · "+next.title+" · "+hhmm(next.start);return s;}
  View guideChannelRow(Channel ch){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),dp(6),dp(8),dp(6));row.setBackground(rounded(Color.argb(232,6,29,50),12));ImageView logo=new ImageView(this);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);row.addView(logo,new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(10),0,dp(5),0);TextView n=tv(ch.name,14,Color.WHITE);n.setTypeface(Typeface.DEFAULT,Typeface.BOLD);n.setSingleLine(true);TextView p=tv(nowNextText(ch),11,MUTED);p.setMaxLines(2);box.addView(n,new LinearLayout.LayoutParams(-1,dp(23)));box.addView(p,new LinearLayout.LayoutParams(-1,dp(38)));row.addView(box,new LinearLayout.LayoutParams(0,dp(61),1));ImageView go=new ImageView(this);go.setImageResource(R.drawable.pv_ic_chevron);go.setPadding(dp(10),dp(10),dp(10),dp(10));row.addView(go,new LinearLayout.LayoutParams(dp(40),dp(40)));bindLogo(logo,ch);return row;}
  void showGuide(){if(programGuide.isEmpty()){if(epgLoading){pvMessage("Programación","La guía EPG se está descargando y procesando.\n\nPuedes seguir usando PalmaVision y volver a Programación en unos momentos.");return;}if(all.isEmpty()){pvMessage("Programación","La lista de canales todavía se está cargando.");return;}String retryUrl=!lastEpgUrl.isEmpty()?lastEpgUrl:detectedPlaylistEpgUrl;if(!retryUrl.isEmpty()){AlertDialog d=new AlertDialog.Builder(this).setTitle("Programación").setMessage(epgLastError.isEmpty()?"La guía todavía no tiene datos disponibles.":"No se pudo cargar la guía.\n\n"+epgLastError+"\n\nURL: "+retryUrl).setNegativeButton("Cerrar",null).setPositiveButton("Reintentar",(x,w)->{loadXmltv(retryUrl,"EPG de la lista");toast("Recargando guía EPG");}).setNeutralButton("Configurar",(x,w)->showLists()).create();styleDialog(d);return;}pvMessage("Programación","Esta lista no incluye una URL EPG/XMLTV.\n\nPuedes agregarla en Configuración → Fuentes de TV → Guía EPG / XMLTV.");return;}setPage("guide","Programación");LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(10),dp(8),dp(10),dp(10));page.setBackground(outlinePanel());contentFrame.addView(page,new FrameLayout.LayoutParams(-1,-1));TextView h=tv("Programación",20,Color.WHITE);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);page.addView(h,new LinearLayout.LayoutParams(-1,dp(38)));TextView s=tv(displayCategory(category)+" · "+activeEpgLabel,12,CYAN);page.addView(s,new LinearLayout.LayoutParams(-1,dp(30)));List<Channel> source=baseForCategory(category);ArrayList<Channel> data=new ArrayList<>();for(Channel ch:source)if(programGuide.containsKey(ch.id))data.add(ch);if(current!=null&&programGuide.containsKey(current.id)&&!data.contains(current))data.add(0,current);ListView lv=new ListView(this);BaseAdapter a=new BaseAdapter(){public int getCount(){return data.size();}public Channel getItem(int p){return data.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup parent){return guideChannelRow(getItem(p));}};lv.setAdapter(a);lv.setDivider(new ColorDrawable(Color.TRANSPARENT));lv.setDividerHeight(dp(5));page.addView(lv,new LinearLayout.LayoutParams(-1,0,1));lv.setOnItemClickListener((p,v,pos,id)->showChannelSchedule(data.get(pos)));if(data.isEmpty()){TextView e=tv("La guía cargada no coincide con los canales de esta categoría.",14,MUTED);page.addView(e,new LinearLayout.LayoutParams(-1,dp(60)));}}

  void showChannelSchedule(Channel ch){setPage("schedule","Programación");LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(10),dp(8),dp(10),dp(10));page.setBackground(outlinePanel());contentFrame.addView(page,new FrameLayout.LayoutParams(-1,-1));TextView h=tv(ch.name,20,Color.WHITE);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);page.addView(h,new LinearLayout.LayoutParams(-1,dp(38)));TextView sub=tv("Programación · próximas 24 horas",12,CYAN);page.addView(sub,new LinearLayout.LayoutParams(-1,dp(28)));List<Program> list=programGuide.get(ch.id);LinearLayout holder=new LinearLayout(this);holder.setOrientation(LinearLayout.VERTICAL);ScrollView scroll=new ScrollView(this);scroll.addView(holder,new ScrollView.LayoutParams(-1,-2));page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));long now=System.currentTimeMillis();if(list!=null)for(Program pr:list){boolean on=now>=pr.start&&now<pr.stop;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(12),dp(8),dp(12),dp(8));row.setBackground(rounded(on?Color.argb(245,0,92,150):PV_SURFACE_2,12));TextView time=tv(hhmm(pr.start)+" – "+hhmm(pr.stop)+(on?" · AHORA":""),11,on?CYAN:MUTED);TextView name=tv(pr.title,14,Color.WHITE);name.setTypeface(Typeface.DEFAULT,Typeface.BOLD);row.addView(time,new LinearLayout.LayoutParams(-1,dp(22)));row.addView(name,new LinearLayout.LayoutParams(-1,dp(28)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(58));rp.setMargins(0,dp(4),0,dp(4));holder.addView(row,rp);}Button watch=primaryBtn("Ver canal");page.addView(watch,new LinearLayout.LayoutParams(-1,dp(52)));watch.setOnClickListener(v->{showLivePlayer(category);play(ch);});}



  String resizeModeName(){switch(resizeMode){case 1:return "Llenar";case 2:return "Estirar";case 3:return "Original";default:return "Ajustar";}}
  void applyResizeMode(PlayerView v){if(v==null)return;int m=AspectRatioFrameLayout.RESIZE_MODE_FIT;if(resizeMode==1)m=AspectRatioFrameLayout.RESIZE_MODE_ZOOM;else if(resizeMode==2)m=AspectRatioFrameLayout.RESIZE_MODE_FILL;else if(resizeMode==3)m=getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE?AspectRatioFrameLayout.RESIZE_MODE_FIXED_HEIGHT:AspectRatioFrameLayout.RESIZE_MODE_FIXED_WIDTH;v.setResizeMode(m);}
  void cycleResizeMode(){resizeMode=(resizeMode+1)%4;applyResizeMode(playerView);savePrefs();toast("Formato: "+resizeModeName());}
  void openFullscreen(){if(current==null){toast("Selecciona un canal primero");return;}final Dialog dlg=new Dialog(this,android.R.style.Theme_Material_NoActionBar_Fullscreen);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);ViewParent old=playerView.getParent();if(old instanceof ViewGroup)((ViewGroup)old).removeView(playerView);root.addView(playerView,new FrameLayout.LayoutParams(-1,-1));applyResizeMode(playerView);ensureSubtitleLayer();LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(12),dp(8),dp(12),dp(12));bar.setBackgroundColor(Color.argb(205,4,12,23));TextView name=tv(current.name,13,Color.WHITE);name.setTypeface(Typeface.DEFAULT,Typeface.BOLD);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);bar.addView(name,new LinearLayout.LayoutParams(0,dp(48),1));Button lang=iconBtn("Idioma",R.drawable.pv_ic_audio),fit=iconBtn(resizeModeName(),R.drawable.pv_ic_crop),close=dangerBtn("Cerrar");LinearLayout.LayoutParams lp1=new LinearLayout.LayoutParams(dp(96),dp(46));lp1.setMargins(dp(6),0,dp(6),0);bar.addView(lang,lp1);LinearLayout.LayoutParams lp2=new LinearLayout.LayoutParams(dp(104),dp(46));lp2.setMargins(dp(6),0,dp(6),0);bar.addView(fit,lp2);LinearLayout.LayoutParams lp3=new LinearLayout.LayoutParams(dp(98),dp(46));lp3.setMargins(dp(6),0,0,0);bar.addView(close,lp3);FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(-1,dp(76),Gravity.BOTTOM);root.addView(bar,bp);lang.setOnClickListener(v->showMediaLanguageMenu());fit.setOnClickListener(v->{cycleResizeMode();fit.setText(resizeModeName());});close.setOnClickListener(v->dlg.dismiss());dlg.setOnDismissListener(d->{attachMainPlayer();if(player!=null)player.setVolume(1f);});dlg.setContentView(root);dlg.show();Window w=dlg.getWindow();if(w!=null){w.setStatusBarColor(Color.BLACK);w.setNavigationBarColor(Color.BLACK);w.getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);}}


  void setLiveStatus(String s,int color){if(status!=null){status.setText(s);status.setTextColor(color);}}
  String channelPositionText(){if(current==null)return "";int i=all.indexOf(current);return i>=0?" · "+(i+1)+"/"+all.size():"";}
  boolean networkConnected(){try{ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network n=cm.getActiveNetwork();if(n==null)return false;NetworkCapabilities cp=cm.getNetworkCapabilities(n);return cp!=null&&cp.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);}catch(Exception e){return true;}}
  void armStartupWatchdog(final int token){cancelStartupWatchdog();startupWatchdog=()->{if(token!=playToken||current==null||player==null||player.getPlaybackState()==Player.STATE_READY)return;setHealth(current,HEALTH_WARN,"Respuesta lenta",0);setLiveStatus("Respuesta lenta · reconectando…",ORANGE);if(autoRetryEnabled)autoRetry();};mainHandler.postDelayed(startupWatchdog,12000);}
  void cancelStartupWatchdog(){if(startupWatchdog!=null){mainHandler.removeCallbacks(startupWatchdog);startupWatchdog=null;}}
  String errorLabel(PlaybackException e){String n=e==null?"":e.getErrorCodeName();String u=n.toUpperCase(Locale.ROOT);if(u.contains("NETWORK")||u.contains("TIMEOUT"))return "Problema de red · reintentando";if(u.contains("BAD_HTTP_STATUS")||u.contains("FILE_NOT_FOUND"))return "Enlace no disponible · reintentando";if(u.contains("PARSING")||u.contains("DECOD"))return "Formato de señal no compatible";return "Canal sin respuesta · reintentando";}
  void validateCurrent(){final Channel ch=current;if(ch==null){toast("Selecciona un canal primero");return;}setLiveStatus("Verificando enlace…",CYAN);io.submit(()->{long t=SystemClock.elapsedRealtime();String result;boolean ok=false;HttpURLConnection h=null;try{URL u=new URL(ch.url);URLConnection raw=u.openConnection();raw.setConnectTimeout(6000);raw.setReadTimeout(6000);raw.setRequestProperty("User-Agent","PalmaVision/2.2.2");if(raw instanceof HttpURLConnection){h=(HttpURLConnection)raw;h.setRequestMethod("GET");h.setRequestProperty("Range","bytes=0-1023");h.setInstanceFollowRedirects(true);int code=h.getResponseCode();ok=code>=200&&code<400;result="HTTP "+code+" · "+(SystemClock.elapsedRealtime()-t)+" ms";}else{raw.connect();ok=true;result=u.getProtocol().toUpperCase(Locale.ROOT)+" · "+(SystemClock.elapsedRealtime()-t)+" ms";}}catch(Exception ex){result="Sin respuesta · "+ex.getClass().getSimpleName();}finally{if(h!=null)h.disconnect();}final boolean good=ok;final String msg=result;final long elapsed=SystemClock.elapsedRealtime()-t;runOnUiThread(()->{lastHealth=msg;if(good)setHealth(ch,elapsed>2500?HEALTH_WARN:HEALTH_OK,elapsed>2500?"Lento":"Disponible",elapsed);else setHealth(ch,HEALTH_BAD,"Sin respuesta",elapsed);setLiveStatus(good?"Canal responde · "+msg:"Sin respuesta · "+msg,good?GREEN:ORANGE);toast(good?"Enlace del canal disponible":"El enlace no respondió a la verificación");});});}

  void styleDialog(AlertDialog d){d.setOnShowListener(x->{Window w=d.getWindow();if(w!=null){w.setBackgroundDrawable(rounded(PV_SURFACE,18));w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams lp=w.getAttributes();lp.dimAmount=.72f;w.setAttributes(lp);}TextView m=d.findViewById(android.R.id.message);if(m!=null){m.setTextColor(Color.WHITE);m.setTextSize(15);}int tid=getResources().getIdentifier("alertTitle","id","android");TextView at=tid==0?null:d.findViewById(tid);if(at!=null){at.setTextColor(Color.WHITE);at.setTextSize(20);}ListView l=d.getListView();if(l!=null){l.setBackgroundColor(PV_SURFACE);l.setDivider(new ColorDrawable(Color.argb(90,0,198,255)));l.setDividerHeight(1);}Button p=d.getButton(AlertDialog.BUTTON_POSITIVE),n=d.getButton(AlertDialog.BUTTON_NEGATIVE),z=d.getButton(AlertDialog.BUTTON_NEUTRAL);if(p!=null)p.setTextColor(CYAN);if(n!=null)n.setTextColor(MUTED);if(z!=null)z.setTextColor(MUTED);});d.show();}
  void pvMessage(String title,String message){AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("Cerrar",null).create();styleDialog(d);}
  void diagnostics(){pvMessage("Diagnóstico PalmaVision","Versión: 2.2.2 Auto Connect\nCanales: "+all.size()+"\nFavoritos: "+favorites.size()+"\nRecientes: "+recents.size()+"\nRed activa: "+(networkConnected()?"Sí":"No")+"\nCanal actual: "+(current==null?"Ninguno":current.name)+"\nÚltima verificación: "+lastHealth+"\nEPG: "+activeEpgLabel+(epgLastError.isEmpty()?"":" · "+epgLastError)+"\nPermisos: INTERNET + ACCESS_NETWORK_STATE\nBuild: release / no-debuggable\nReproductor: Media3 / ExoPlayer");}
