  void loadSavedSource(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);String type=p.getString("source_type",""),uri=p.getString("m3u_uri",""),url=p.getString("m3u_url",""),epg=p.getString("epg_url","");if("xtream".equals(type)){String n=p.getString("xtream_name","Mi IPTV"),s=p.getString("xtream_server",""),u=p.getString("xtream_user",""),pw=p.getString("xtream_pass","");if(!s.isEmpty()&&!u.isEmpty()&&!pw.isEmpty()){loadXtream(s,u,pw,n);return;}}if("local".equals(type)&&!uri.isEmpty()){if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadFromUri(Uri.parse(uri),"Archivo M3U local");return;}if("url".equals(type)&&!url.isEmpty()){if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadFromUrl(url,"URL M3U");return;}if(!uri.isEmpty()){if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadFromUri(Uri.parse(uri),"Archivo M3U local");return;}if(!url.isEmpty()){if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadFromUrl(url,"URL M3U");return;}if(!epg.isEmpty())queueEpg(epg,"XMLTV");loadDefault();}
  void loadDefault(){setLoading("Cargando lista…","Lista principal");io.submit(()->{List<Channel> parsed;try{parsed=parse(getAssets().open("TV_Espanol_Plus_VERIFICADA.m3u"));}catch(Exception e){parsed=Collections.emptyList();}applyChannels(parsed,"Lista principal");});}
  void loadFromUrl(String url,String label){setLoading("Cargando M3U…",label);io.submit(()->{try{URLConnection c=new URL(url).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(9000);c.setRequestProperty("User-Agent","PalmaVision/2.2.2");List<Channel> p=parse(c.getInputStream());if(p.isEmpty())throw new IOException("Lista vacía");applyChannels(p,label);}catch(Exception e){runOnUiThread(()->toast("No se pudo cargar la lista: "+e.getMessage()));}});}
  void loadFromUri(Uri uri,String label){setLoading("Leyendo archivo M3U…",label);io.submit(()->{try(InputStream in=getContentResolver().openInputStream(uri)){List<Channel> p=parse(in);if(p.isEmpty())throw new IOException("Lista vacía");applyChannels(p,label);}catch(Exception e){runOnUiThread(()->toast("No se pudo leer M3U: "+e.getMessage()));}});}
  void setLoading(String s,String src){runOnUiThread(()->{if(count!=null)count.setText(s);if(sourceText!=null)sourceText.setText(src);});}
  void applyChannels(List<Channel> p,String label){runOnUiThread(()->{all.clear();all.addAll(p);channelHealth.clear();for(Channel ch:p)if(ch.score>=90)channelHealth.put(ch.id,new Health(HEALTH_VERIFIED,"Verificado",0,System.currentTimeMillis()));activeSourceLabel=label;rebuildChannelIndex();if(sourceText!=null)sourceText.setText(label);SharedPreferences sp=getSharedPreferences("tvplus",MODE_PRIVATE);String type=sp.getString("source_type",""),manualEpg=sp.getString("epg_url","");String epgToLoad="",epgLabel="";if(!pendingEpgUrl.isEmpty()){epgToLoad=pendingEpgUrl;epgLabel=pendingEpgLabel;pendingEpgUrl="";pendingEpgLabel="";}else if(!manualEpg.isEmpty()){epgToLoad=manualEpg;epgLabel="XMLTV";}else if(!"xtream".equals(type)&&!detectedPlaylistEpgUrl.isEmpty()){epgToLoad=detectedPlaylistEpgUrl;epgLabel="EPG de la lista";}if(!epgToLoad.isEmpty()&&!epgToLoad.equals(lastEpgUrl))loadXmltv(epgToLoad,epgLabel);if(adapter!=null)filter();if("livecats".equals(page))showLiveCategories();else if("countries".equals(page))showCountries();});}

  void loadPrefs(){SharedPreferences p=getSharedPreferences("tvplus",MODE_PRIVATE);favorites.addAll(p.getStringSet("favorites",Collections.emptySet()));blockedChannels.addAll(p.getStringSet("blocked_channels",Collections.emptySet()));String r=p.getString("recents","");if(!r.isEmpty())for(String s:r.split("\\|"))if(!s.isEmpty())recents.add(s);autoRetryEnabled=p.getBoolean("auto_retry",true);resizeMode=p.getInt("resize_mode",0);preferredAudioLang=p.getString("preferred_audio","auto");preferredSubtitleLang=p.getString("preferred_subtitle","auto");parentalEnabled=p.getBoolean("parental_enabled",false);parentalPinHash=p.getString("parental_pin_hash","");}
  void savePrefs(){getSharedPreferences("tvplus",MODE_PRIVATE).edit().putStringSet("favorites",new HashSet<>(favorites)).putStringSet("blocked_channels",new HashSet<>(blockedChannels)).putString("recents",joinRecents()).putBoolean("auto_retry",autoRetryEnabled).putInt("resize_mode",resizeMode).putString("preferred_audio",preferredAudioLang).putString("preferred_subtitle",preferredSubtitleLang).putBoolean("parental_enabled",parentalEnabled).putString("parental_pin_hash",parentalPinHash==null?"":parentalPinHash).apply();}
  String joinRecents(){StringBuilder b=new StringBuilder();for(String id:recents){if(b.length()>0)b.append("|");b.append(id);}return b.toString();}

  @Override public boolean dispatchKeyEvent(KeyEvent e){if(e.getAction()==KeyEvent.ACTION_DOWN){if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_NEXT){step(1);return true;}if(e.getKeyCode()==KeyEvent.KEYCODE_MEDIA_PREVIOUS){step(-1);return true;}}return super.dispatchKeyEvent(e);}
  @Override public void onBackPressed(){if("dualpicker".equals(page)){showDualView();}else if("dual".equals(page)){showHome();}else if("schedule".equals(page)){showGuide();}else if("guide".equals(page)){showLivePlayer(category);}else if("live".equals(page)){showLiveCategories();}else if("countries".equals(page)){showLiveCategories();}else if("livecats".equals(page)){showHome();}else if(!"home".equals(page)){showHome();}else confirmExit();}
  @Override protected void onDestroy(){cancelStartupWatchdog();mainHandler.removeCallbacksAndMessages(null);try{if(castContext!=null&&castSessionListener!=null)castContext.getSessionManager().removeSessionManagerListener(castSessionListener,CastSession.class);}catch(Exception ignored){}try{if(mediaRouter!=null&&castRouteCallback!=null)mediaRouter.removeCallback(castRouteCallback);}catch(Exception ignored){}super.onDestroy();if(player!=null)player.release();if(dualPlayer!=null)dualPlayer.release();io.shutdownNow();imageIo.shutdownNow();epgIo.shutdownNow();tvIo.shutdownNow();}

  static final Pattern GROUP=Pattern.compile("group-title=\\\"([^\\\"]*)\\\""),ID=Pattern.compile("tvg-id=\\\"([^\\\"]*)\\\""),LOGO=Pattern.compile("tvg-logo=\\\"([^\\\"]*)\\\""),EPG=Pattern.compile("(?:x-tvg-url|url-tvg)=\\\"([^\\\"]+)\\\"",Pattern.CASE_INSENSITIVE),SCORE=Pattern.compile("nexus-score=\\\"?(\\d+)\\\"?");
  List<Channel> parse(InputStream in)throws IOException{ArrayList<Channel> out=new ArrayList<>();if(in==null)return out;String epg="";try(BufferedReader br=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){String line,meta=null;while((line=br.readLine())!=null){line=line.replace("\uFEFF","").trim();if(line.startsWith("#EXTM3U")){Matcher em=EPG.matcher(line);if(em.find())epg=em.group(1).trim();continue;}if(line.startsWith("#EXTINF:"))meta=line;else if(!line.isEmpty()&&!line.startsWith("#")&&meta!=null){String name=meta.contains(",")?meta.substring(meta.lastIndexOf(',')+1).trim():"Canal";Matcher gm=GROUP.matcher(meta),im=ID.matcher(meta),lm=LOGO.matcher(meta),sm=SCORE.matcher(meta);String group=gm.find()?gm.group(1):"Otros";String id=im.find()&&im.group(1).trim().length()>0?im.group(1):sha1(name+"|"+line);String logo=lm.find()?lm.group(1).trim():"";int score=sm.find()?Integer.parseInt(sm.group(1)):0;out.add(new Channel(id,name,group,line,logo,score));meta=null;}}}detectedPlaylistEpgUrl=epg;return out;}

  static String sha1(String s){try{byte[] b=MessageDigest.getInstance("SHA-1").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder x=new StringBuilder();for(byte v:b)x.append(String.format("%02x",v));return x.toString();}catch(Exception e){return Integer.toHexString(s.hashCode());}}
